
insert into public.courses (slug,title,short_description,description,suitable_for,curriculum,outcomes,icon,sort_order,disclaimer,objectives) values
('cryptocurrency-trading','Cryptocurrency Trading','Blockchain, digital assets, exchanges, wallets and responsible trading.','A beginner-friendly programme introducing cryptocurrency, blockchain technology, digital assets, exchanges, wallets, trading, and risk management.','Beginners and anyone curious about digital assets who wants to use crypto platforms safely.',
array['Introduction to cryptocurrency and blockchain technology','Bitcoin, Ethereum, stablecoins, and other digital assets','Centralised exchanges and decentralised exchanges','Cryptocurrency wallets, private keys, and wallet security','Buying, selling, and exchanging digital currencies','Spot trading and market analysis','Peer-to-peer cryptocurrency transactions','Introduction to decentralised finance','Trading strategies and risk management','Cryptocurrency scams, fraud prevention, and security','Responsible use of cryptocurrency platforms'],
'Students should understand how cryptocurrency markets and platforms operate and acquire foundational practical skills for using them responsibly.','bitcoin',1,'This course is educational and is not personalised financial advice. Trading involves risk; no profits are guaranteed.',
array['Understand blockchain and the main types of digital assets','Use exchanges and wallets securely','Apply basic market analysis and risk management','Recognise and avoid common crypto scams']),
('forex-trading','Forex Trading','Currency markets, chart analysis, MetaTrader and risk management.','A structured introduction to the foreign exchange market, currency trading, chart analysis, trading platforms, and risk management.','Beginners who want a structured, risk-aware introduction to currency trading.',
array['Introduction to the foreign exchange market','Currency pairs, pips, spreads, and lot sizes','Exchange rates and market sessions','Forex brokers and trading accounts','MetaTrader 4 and MetaTrader 5','Candlestick charts and price action','Technical and fundamental analysis','Market trends, support, and resistance','Trading strategies and trade execution','Entry and exit planning','Stop-loss and take-profit orders','Leverage and margin','Risk management and trading psychology','Demo trading and performance evaluation'],
'Students should understand forex trading mechanics, interpret basic currency charts, practise using demo accounts, and understand the risks of leveraged trading.','trending',2,'This course is educational and is not personalised financial advice. Leveraged trading carries a high risk of loss.',
array['Explain how the forex market works','Read candlestick charts and price action','Use MetaTrader on a demo account','Plan trades with stop-loss and risk limits']),
('web-design-development','Web Design and Development','Plan, design, build and publish websites for real clients.','Training in planning, designing, building, publishing, and maintaining websites for businesses, schools, organisations, and individuals.','Aspiring web designers, entrepreneurs and freelancers.',
array['Introduction to websites and web technologies','Website planning and structure','User interface and user experience principles','HTML, CSS, and introductory JavaScript','Responsive website design','Website builders and AI-assisted development','Business websites and portfolio websites','Domains and web hosting','Website publication and deployment','Content management','Website maintenance and basic security','Website performance and accessibility','Freelancing and website service delivery'],
'Students should understand the website development process and be able to create functional websites using appropriate coding tools or website-building platforms.','code',3,'',
array['Plan and structure a website','Build responsive pages with HTML and CSS','Publish a site on a domain','Deliver website services to clients']),
('graphic-designing','Graphic Designing','Branding, logos, social graphics and print-ready designs.','Practical training in visual communication and the creation of professional designs for businesses, brands, social media, and marketing.','Creatives, small business owners and aspiring freelance designers.',
array['Introduction to graphic design','Colour theory and typography','Layout, alignment, and composition','Branding and visual identity','Logo design','Flyers, posters, banners, and brochures','Social media graphics','Advertising creatives','Image editing and manipulation','Canva and other suitable design tools','AI-assisted graphic design','Exporting designs for print and digital use','Portfolio development','Freelancing and client management'],
'Students should be able to create professional designs for personal projects, commercial clients, brands, and digital platforms.','palette',4,'',
array['Apply colour, type and layout principles','Design logos and brand assets','Create social media and print materials','Build a design portfolio']),
('artificial-intelligence-tools','Artificial Intelligence Tools','Use AI for productivity, research, design and business.','A practical programme teaching students to use artificial intelligence tools for productivity, research, writing, design, automation, and digital business operations.','Students, professionals and business owners who want to work smarter with AI.',
array['Introduction to artificial intelligence','Generative AI and AI assistants','Large language models and their capabilities','Prompt engineering and effective prompting','AI-assisted writing and research','Summarisation and information analysis','AI image generation','AI-assisted graphic design','AI-assisted video and audio production','AI tools for business productivity','AI-assisted website development and coding','Introduction to workflow automation','Evaluating AI-generated information','Data privacy, ethics, and responsible AI use','Digital business opportunities involving AI tools'],
'Students should be able to select and use appropriate AI tools to improve productivity, solve practical problems, and support creative or business activities.','sparkles',5,'',
array['Write effective prompts','Use AI for writing, research and design','Automate simple workflows','Use AI responsibly and check its output']),
('financial-markets-investment','Other Financial Markets and Investment Education','Stocks, bonds, funds, commodities and how investors evaluate risk.','A financial-market education programme covering investment instruments and markets beyond cryptocurrency and forex. The course explains how these markets work, how financial instruments differ, and how investors evaluate risk.','Anyone who wants to understand investing and financial markets in Nigeria and internationally.',
array['Introduction to financial markets','Stock markets and publicly listed companies','Shares, equities, dividends, and capital gains','Government bonds and corporate bonds','Treasury bills and money-market instruments','Mutual funds','Exchange-traded funds','Stock market indices','Commodities such as gold, crude oil, and agricultural products','Futures and options','Real Estate Investment Trusts','Brokerage accounts and investment platforms','Buying and selling securities','Fundamental analysis','Introductory technical analysis','Portfolio diversification and asset allocation','Inflation, liquidity, and investment risk','Investor protection and financial fraud prevention','Introduction to Nigerian and international financial markets'],
'Students should understand the principal financial instruments, how markets operate, and how to evaluate investment opportunities and associated risks.','landmark',6,'This programme is for education only and is not personalised financial advice. We do not promise profits, guaranteed returns or risk-free investments.',
array['Distinguish the main financial instruments','Understand how securities are bought and sold','Evaluate risk, liquidity and diversification','Recognise investment fraud']),
('social-media-production','Social Media Production','Content strategy, short-form video and audience growth.','A practical programme in digital content creation, short-form video production, social media management, audience development, and content strategy.','Content creators, brand managers and small businesses.',
